"use client"

import { useBannedUsers } from "@/src/lib/ReactQuery/query/admin/users/ban/query";
import { useGetUsers } from "@/src/lib/ReactQuery/query/admin/users/query"
import { TUser } from "@/src/types";
import { zodResolver } from "@hookform/resolvers/zod";
import { useState } from "react";
import { useForm } from "react-hook-form";
import z from "zod";

const banSchema = z.object({
    id: z.string(),
    isBanned: z.enum(["true", "false"]),
    bannedUntil: z.string(),
    banReason: z.string().min(1, "Укажите причину")
});
type TBanSchema = z.infer<typeof banSchema>;

export default function UsersPage() {
    const usersGet = useGetUsers();
    const [isOpenBan, setIsOpenBan] = useState<boolean>(false);
    const banUser = useBannedUsers();
    const { register, handleSubmit, formState: { errors }, reset, watch } = useForm<TBanSchema>({
        resolver: zodResolver(banSchema),
        defaultValues: { id: "", isBanned: "false", bannedUntil: "", banReason: "" }
    });
    const isBannedWatch = watch("isBanned");
    async function onSubmit(data: TBanSchema) {
        banUser.mutate(data, {
            onSuccess: () => {
                reset();
                setIsOpenBan(false);
            }
        });
    }
    return<main>
        <h3>Пользователи</h3>
        <section>
            {usersGet.isLoading && <p>Загрузка пользователей...</p>}
            {!usersGet.data || usersGet.data.length < 1 && <p>Пользователей пока нет</p>}
            <table>
                <thead>
                    <td>id</td>
                    <td>Имя</td>
                </thead>
                <tbody>
                    {usersGet.data && usersGet.data.length > 0 && usersGet.data.map((user: TUser) => {

                        return<tr key={user.id}>
                            <td>{(user.id).slice(0,8)}</td>
                            <td>{user.username}</td>
                            <td>
                                <button onClick={() => {
                                    reset({ id: user.id, isBanned: "true", bannedUntil: "", banReason: "" })
                                }}>Забанить</button>
                            </td>
                        </tr>
                    })}
                </tbody>
            </table>
        </section>
    </main>
}